#!/usr/bin/env python3
"""Build a standalone simulation of the six T5 questions and the 12 approved simple-French screens."""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", type=Path, default=ROOT / "simulation/T5_12_ECRANS_EXECUTABLE.html")
    args = parser.parse_args()
    questions_path = ROOT / "form/questions_T5.json"
    flow_path = ROOT / "config/T5_CAPTURE_FLOW_V1_0_0.json"
    questions = json.loads(questions_path.read_text(encoding="utf-8"))
    flow = json.loads(flow_path.read_text(encoding="utf-8"))
    if len(questions["fields"]) != 6 or len(flow["screens"]) != 12:
        raise SystemExit("T5 simulation requires exactly six questions and twelve screens")
    q_json = json.dumps(questions, ensure_ascii=False).replace("</", "<\\/")
    f_json = json.dumps(flow, ensure_ascii=False).replace("</", "<\\/")
    template = r'''<!doctype html>
<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>T5 — 6 questions et 12 écrans en français simple</title>
<style>
:root{--ink:#241d19;--cream:#f7f0e6;--paper:#fffaf3;--red:#c43e2a;--green:#2f7052;--gold:#d99037;--dark:#141010;--muted:#695b52;--line:#493c34}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 12% 10%,#432920 0,#171719 38%,#08090a 100%);color:#f7eee3;font:15px/1.42 ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}.shell{max-width:1190px;margin:auto;padding:22px;display:grid;grid-template-columns:270px minmax(340px,430px) minmax(270px,1fr);gap:22px;align-items:start}.panel{background:#151719eb;border:1px solid #40372f;border-radius:22px;box-shadow:0 26px 70px #0008}.side{padding:22px;position:sticky;top:22px}.eyebrow{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:#e8ba7a;font-weight:900}.side h1{font:800 29px/1.02 Georgia,serif;margin:10px 0}.side p{color:#c4b9ad}.stat{display:flex;justify-content:space-between;border-top:1px solid #3a332d;padding:11px 0}.stat b{color:#f0c889}.routes{width:100%;background:#0e1011;color:#eee;border:1px solid #4c4239;border-radius:12px;padding:10px;margin:8px 0 16px}.nav{display:grid;grid-template-columns:1fr 1fr;gap:8px}.btn{border:0;border-radius:12px;padding:12px 13px;font-weight:900;cursor:pointer;background:#ead9c2;color:#21170e}.btn.primary{background:linear-gradient(135deg,#bf472f,#dc7245);color:white}.btn.ghost{background:#292826;color:#eee;border:1px solid #62574f}.btn:disabled{opacity:.35;cursor:not-allowed}.phone{padding:10px;background:#050606;border:1px solid #413a34;border-radius:36px;box-shadow:0 35px 75px #000a;min-height:770px}.screen{height:748px;border-radius:27px;overflow:auto;position:relative;background:#18130f}.camera{position:absolute;inset:0;background:radial-gradient(circle at 72% 24%,#d99a3f44 0 4%,transparent 5%),radial-gradient(circle at 22% 34%,#d99a3f33 0 3%,transparent 4%),linear-gradient(155deg,#17100b 0,#76513d 38%,#2a1f1a 70%,#100d0b 100%)}.camera:before{content:"";position:absolute;width:210px;height:410px;left:50%;top:18%;transform:translateX(-50%);border-radius:100px 100px 22px 22px;background:linear-gradient(#e7c0a277,#322018aa);filter:blur(2px)}.shade{position:absolute;inset:0;background:linear-gradient(#0006,#0001 38%,#000d)}.screen-label{font-size:10px;letter-spacing:.09em;font-weight:900}.scene-counter{font-size:12px;letter-spacing:.04em;font-weight:900}.guide-head{position:relative;z-index:2;min-height:140px;padding:23px 22px 16px;background:#120e0ebd}.guide-head h2{font:900 29px/1.05 ui-sans-serif,system-ui;margin:10px 0 0}.guide-body{position:relative;z-index:2;background:var(--cream);color:var(--ink);min-height:608px;border-radius:24px 24px 0 0;padding:21px 22px}.guide-body h3{font-size:12px;letter-spacing:.08em;color:var(--red);margin:12px 0 5px}.guide-body h3.good{color:var(--green)}.guide-body p{margin:5px 0}.guide-body ul{padding-left:20px;margin:5px 0}.guide-body li{margin:4px 0}.consent{background:#efe0bb;border:1px solid #d3ae61;border-radius:12px;padding:10px;margin:12px 0!important}.speech{color:var(--muted);font-size:13px}.guide-body .btn{width:100%;margin-top:17px}.recording{position:relative;z-index:2;height:748px;padding:24px 20px;display:flex;flex-direction:column}.record-top{display:flex;justify-content:space-between;gap:12px}.record-meta{background:#0a0808cc;border-radius:15px;padding:12px 14px;flex:1}.rec{align-self:flex-start;background:#b31e1b;border-radius:999px;padding:9px 16px;font-weight:900;box-shadow:0 0 0 6px #b31e1b2c}.record-middle{margin:auto 0;text-align:center}.prompt{font-size:22px;font-weight:900;letter-spacing:.04em;background:#0b0909df;border:1px solid #d6a35f99;padding:22px 15px;border-radius:16px}.timer{display:inline-block;margin-top:17px;background:#0b0909dd;padding:11px 18px;border-radius:13px;font-weight:900}.status-list{display:grid;gap:9px}.status{background:#0a0909d9;border-radius:12px;padding:11px 13px;font-weight:800}.status:before{content:"●";color:#58c889;margin-right:9px}.bar{height:8px;background:#ffffff3b;border-radius:10px;overflow:hidden;margin-top:14px}.bar span{display:block;height:100%;background:var(--red);width:0}.review{position:relative;z-index:2;height:748px;display:flex;flex-direction:column}.review-top{background:#090808e6;padding:22px}.review-top h2{margin:10px 0 4px}.audio{font-weight:800}.audio:before{content:"●";color:#59ca8a;margin-right:9px}.preview{height:275px;background:linear-gradient(150deg,#312019,#825b43 52%,#1b1512);border-top:1px solid #a76d4355;border-bottom:1px solid #a76d4355}.review-card{margin-top:auto;background:#171212;color:#fff;border-radius:27px 27px 0 0;padding:24px 22px}.review-card h3{font-size:21px;line-height:1.15;margin:0 0 17px}.checks{list-style:none;padding:0;margin:0}.checks li{margin:9px 0}.checks li:before{content:"✓";display:inline-grid;place-items:center;color:#67d99b;border:2px solid #67d99b;border-radius:50%;width:19px;height:19px;font-size:12px;font-weight:900;margin-right:9px}.actions{display:grid;grid-template-columns:1fr 1.6fr;gap:9px;margin-top:24px}.form-screen{height:748px;background:linear-gradient(160deg,#f7efe3,#e6d3ba);color:var(--ink);padding:26px 22px;overflow:auto}.form-screen h2{font:800 31px/1.05 Georgia,serif}.field{margin:16px 0}.field label{font-weight:900;display:block;margin-bottom:4px}.field-question{margin:0 0 7px;color:#55483f}.field small{display:block;color:#695f55;margin-top:4px}.field input,.field textarea{width:100%;border:1px solid #b8a48d;border-radius:11px;padding:11px;background:#fffaf3;font:inherit}.field textarea{min-height:82px;resize:vertical}.field input:focus,.field textarea:focus{outline:3px solid #d39a5c55;border-color:#a65c34}.field-example{display:flex;align-items:flex-start;gap:7px;color:#695f55;font-size:13px;margin-top:5px}.field-example b{color:#9d4a2e;white-space:nowrap}.field-example ul{margin:0;padding-left:17px}.field-example span{white-space:pre-line}.error{color:#9d3024;font-weight:900;min-height:20px}.detail{padding:22px}.detail h2{font:700 25px/1.1 Georgia,serif}.code{background:#0b0c0d;border:1px solid #3b3834;color:#d8c9b6;border-radius:14px;padding:12px;max-height:330px;overflow:auto;font:12px/1.45 ui-monospace,monospace;white-space:pre-wrap}.binding{color:#c9b69e;border-bottom:1px solid #3a342e;padding:8px 0}.success{color:#a9d2ad}@media(max-width:980px){.shell{grid-template-columns:230px minmax(340px,430px)}.detail{grid-column:1/-1}.side{position:static}}@media(max-width:700px){.shell{display:block;padding:10px}.side,.phone,.detail{margin-bottom:14px}.phone{min-height:auto}.screen,.form-screen{height:710px}}
</style></head><body><main class="shell"><aside class="panel side"><div class="eyebrow">RESTAURATION‑T5</div><h1>Formule, combo et offre</h1><p>Parcours en français simple, relié aux six questions et aux quatre vidéos.</p><div class="stat"><span>Questions</span><b>6</b></div><div class="stat"><span>Scènes</span><b>4</b></div><div class="stat"><span>Écrans</span><b>12</b></div><label for="routes" class="eyebrow">Choisir un écran</label><select id="routes" class="routes"></select><div class="nav"><button class="btn ghost" id="prev">← Précédent</button><button class="btn ghost" id="next">Suivant →</button></div><p id="sourceStatus" class="success"></p></aside><section class="phone"><div id="stage" class="screen"></div></section><aside class="panel detail"><div class="eyebrow">Données utilisées</div><h2 id="detailTitle">Six réponses</h2><div id="bindings"></div><h3>État JSON</h3><pre id="json" class="code"></pre></aside></main>
<script type="application/json" id="questions">__QUESTIONS__</script><script type="application/json" id="flow">__FLOW__</script>
<script>
const questions=JSON.parse(document.querySelector('#questions').textContent);const flow=JSON.parse(document.querySelector('#flow').textContent);const screens=flow.screens;let route=-1;let timer=null;const payload={};
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function init(){const select=$('#routes');select.innerHTML='<option value="-1">6 questions avant de filmer</option>'+screens.map((s,i)=>`<option value="${i}">${String(i+1).padStart(2,'0')} · ${esc(s.display_state)} · ${esc(s.scene_id)}</option>`).join('');select.onchange=()=>go(Number(select.value));$('#prev').onclick=()=>go(Math.max(-1,route-1));$('#next').onclick=()=>go(Math.min(screens.length-1,route+1));$('#sourceStatus').textContent='JSON relié · 6 questions · 12 écrans';go(-1)}
function go(index){if(timer){clearInterval(timer);timer=null}route=index;$('#routes').value=String(route);$('#prev').disabled=route<0;$('#next').disabled=route>=screens.length-1;if(route<0)renderForm();else renderScreen(screens[route]);}
function renderForm(){const fields=questions.fields.map((f,index)=>{const attrs=`id="f_${esc(f.id)}" data-id="${esc(f.id)}" minlength="${f.minLength}" maxlength="${f.maxLength}" ${f.pattern?`pattern="${esc(f.pattern)}"`:''} placeholder="${esc(f.example??'')}" aria-describedby="q_${esc(f.id)} ex_${esc(f.id)}"`;const control=f.id==='contenu'?`<textarea ${attrs}>${esc(payload[f.id]??'')}</textarea>`:`<input ${attrs} value="${esc(payload[f.id]??'')}">`;const example=Array.isArray(f.example_items)?`<ul>${f.example_items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:`<span>${esc(f.example??'')}</span>`;return `<div class="field"><div class="eyebrow">Question ${String(index+1).padStart(2,'0')}</div><label for="f_${esc(f.id)}">${esc(f.label)}${f.required?' *':''}</label><p class="field-question" id="q_${esc(f.id)}">${esc(f.question)}</p>${control}<div class="field-example" id="ex_${esc(f.id)}"><b>Exemple :</b>${example}</div>${f.helper?`<small>${esc(f.helper)}</small>`:''}</div>`}).join('');$('#stage').className='form-screen';$('#stage').innerHTML=`<div class="eyebrow">Avant de filmer</div><h2>Réponds à 6 questions</h2><p>Écris seulement des informations vraies. Les six réponses sont obligatoires et concernent une seule formule.</p>${fields}<div id="formError" class="error"></div><button id="start" class="btn primary" style="width:100%">VOIR LES 12 ÉCRANS</button>`;$('#start').onclick=()=>{let error='';questions.fields.forEach(f=>{const input=$(`#f_${f.id}`);const value=input.value.replace(/\s+/g,' ').trim();payload[f.id]=value;if(f.required&&!value)error=`Réponds à la question « ${f.question} »`;if(value.length<f.minLength||value.length>f.maxLength)error=`La réponse « ${f.id} » n'a pas la bonne longueur.`;if(f.pattern&&value&&!new RegExp(f.pattern).test(value))error=`Le format de la réponse « ${f.id} » n'est pas accepté.`});$('#formError').textContent=error;if(!error){try{localStorage.setItem('t5_merchant_payload',JSON.stringify(payload))}catch(e){}go(0)}};detail('6 réponses reliées à la vidéo',questions.fields.map(f=>[f.id,f.json_target]),{merchant_payload:payload,source:'form/questions_T5.json'})}
function renderScreen(s){$('#stage').className='screen';const r=s.resolved_text||{};let body='';if(s.state==='A_GUIDE'){body=`<div class="camera"></div><div class="guide-head"><div class="screen-label">${esc(r.screen_label)}</div><div class="scene-counter">${esc(r.scene_counter)}</div><h2>${esc(r.title)}</h2></div><div class="guide-body"><h3>${esc(r.guide_section_title)}</h3><p>${esc(r.instruction)}</p><h3 class="good">${esc(r.film_section_title)}</h3><ul>${(r.film_list||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>${esc(r.avoid_section_title)}</h3><ul>${(r.avoid_list||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>${esc(r.action_section_title)}</h3><p>${esc(r.required_action)}</p><h3 class="good">${esc(r.speech_section_title)}</h3><p class="speech">${esc(r.speech_note)}</p><h3>${esc(r.example_section_title)}</h3><p class="consent">${esc(r.optional_example)}</p><button class="btn primary action">${esc(r.primary_action)}</button></div>`}else if(s.state==='B_RECORDING'){body=`<div class="camera"></div><div class="shade"></div><div class="recording"><div class="record-top"><div class="record-meta"><div class="screen-label">${esc(r.screen_label)}</div><div class="scene-counter">${esc(r.scene_counter)}</div></div><div class="rec">${esc(r.recording_status)}</div></div><div class="record-middle"><div class="prompt">${esc(r.instruction)}</div><div id="timer" class="timer">${esc(r.timer_initial)}</div><div class="bar"><span id="recordProgress"></span></div></div><div class="status-list"><div class="status">${esc(r.audio_status)}</div><div class="status">${esc(r.orientation_status)}</div><div class="status">${esc(r.auto_stop_status)}</div></div></div>`}else{body=`<div class="camera"></div><div class="review"><div class="review-top"><div class="screen-label">${esc(r.screen_label)}</div><h2>${esc(r.take_label)}</h2><div class="audio">${esc(r.audio_status)}</div></div><div class="preview" aria-label="Aperçu de la vidéo filmée"></div><div class="review-card"><h3>${esc(r.review_question)}</h3><ul class="checks">${(r.review_checks||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="actions"><button id="retake" class="btn ghost">${esc(r.redo_action)}</button><button id="accept" class="btn primary">${esc(r.positive_action)}</button></div></div></div>`}$('#stage').innerHTML=body;if(s.state==='A_GUIDE')$('.action').onclick=()=>go(route+1);if(s.state==='B_RECORDING')setTimeout(()=>simulateRecording(s,route),120);if(s.state==='C_REVIEW'){$('#retake').onclick=()=>go(route-2);$('#accept').onclick=()=>route===screens.length-1?renderConfirmation():go(route+1)}detail(s.screen_id,Object.entries(s.bindings||{}),s)}
function renderConfirmation(){if(timer){clearInterval(timer);timer=null}route=screens.length;$('#routes').value='';$('#prev').disabled=false;$('#next').disabled=true;$('#stage').className='form-screen';$('#stage').innerHTML=`<div class="eyebrow">T5 · 4 prises acceptées</div><h2>Ton montage peut être créé</h2><p>Les quatre scènes gardent la même formule : le même plat, la même boisson et les mêmes accompagnements.</p><div class="consent"><b>30 secondes</b><br>6 s · 8 s · 7 s · 9 s</div><button id="backToReview" class="btn ghost" style="width:100%">REVOIR LA DERNIÈRE PRISE</button>`;$('#backToReview').onclick=()=>go(screens.length-1);detail('T5_RENDER_CONFIRMATION',[['scènes acceptées','4'],['durée totale','30 secondes']],{next_screen_id:'T5_RENDER_CONFIRMATION',merchant_payload:payload,captures:['S1','S2','S3','S4']})}
function simulateRecording(s,startedRoute){const duration=s.capture_duration_ms,started=Date.now(),r=s.resolved_text;timer=setInterval(()=>{if(route!==startedRoute){clearInterval(timer);timer=null;return}const elapsed=Math.min(duration,Date.now()-started),seconds=Math.floor(elapsed/1000);$('#timer').textContent=`00:${String(seconds).padStart(2,'0')} / ${r.timer_total}`;$('#recordProgress').style.width=`${elapsed/duration*100}%`;if(elapsed>=duration){clearInterval(timer);timer=null;setTimeout(()=>{if(route===startedRoute)go(route+1)},250)}},80)}
function detail(title,bindings,data){$('#detailTitle').textContent=title;$('#bindings').innerHTML=bindings.map(([k,v])=>`<div class="binding"><b>${esc(k)}</b><br>${esc(v)}</div>`).join('');$('#json').textContent=JSON.stringify(data,null,2)}init();
</script></body></html>'''
    rendered = template.replace("__QUESTIONS__", q_json).replace("__FLOW__", f_json)
    provenance = f"<!-- generated from form/questions_T5.json sha256={digest(questions_path)} and config/T5_CAPTURE_FLOW_V1_0_0.json sha256={digest(flow_path)} -->\n"
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(provenance + rendered + "\n", encoding="utf-8")
    print(f"T5_SIMULATION_BUILT {args.output} 6 questions 12 screens simple French")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
